```openscad
// T-slot nut for aluminium extrusion
// Print orientation: flange down on the bed (z = 0), neck building upward.

// ---------- Dimensions (mm) ----------
nut_length     = 20;   // length of the profile along X
flange_width   = 12;   // bottom flange width (Y)
flange_thick   = 2;    // bottom flange thickness, z = 0 .. 2
neck_width     = 6;    // centred neck width (Y)
total_height   = 6;    // top of neck (z)
hole_d         = 3.4;  // vertical screw clearance hole diameter
eps            = 0.5;  // cutter overshoot past faces

$fn = 64;

// ---------- Model ----------
difference() {
    union() {
        // Bottom flange
        translate([-nut_length/2, -flange_width/2, 0])
            cube([nut_length, flange_width, flange_thick]);

        // Neck (overlaps the flange slightly so the union is one solid)
        translate([-nut_length/2, -neck_width/2, flange_thick - 0.01])
            cube([nut_length, neck_width, total_height - flange_thick + 0.01]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = total_height + 2*eps, $fn = 64);
}
```

