// T-slot nut for aluminium extrusion
// Print orientation: flange down on the bed, neck building upward (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
nut_length      = 15;   // length along X
flange_width    = 10;   // bottom flange width (Y)
flange_height   = 3;    // flange thickness, z = 0 .. 3
neck_width      = 7;    // neck width (Y), centred
total_height    = 6;    // top of neck (z)
hole_d          = 3.4;  // vertical screw clearance hole diameter
cut_extra       = 0.5;  // extra length on cutters to avoid coplanar faces

neck_height = total_height - flange_height;  // neck rises from z = 3 to z = 6

difference() {
    union() {
        // Bottom flange
        translate([-nut_length/2, -flange_width/2, 0])
            cube([nut_length, flange_width, flange_height]);

        // Neck (slightly overlapped into flange for a clean union)
        translate([-nut_length/2, -neck_width/2, flange_height - 0.01])
            cube([nut_length, neck_width, neck_height + 0.01]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = total_height + 2*cut_extra);
}
