```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Units: mm. Print orientation: flat on bed, top face up.

$fn = 128;

// --- Ring dimensions ---
outer_d   = 50;    // outer diameter
inner_d   = 26;    // inner (bore) diameter
thickness = 4;     // ring thickness (Z)

// --- Tick marks ---
tick_count  = 12;   // number of evenly spaced ticks
tick_width  = 1.2;  // groove width
tick_depth  = 1.5;  // groove depth from top face
tick_length = 3;    // radial length inward from outer edge
start_angle = 0;    // first tick on +X axis

// --- Clearances for clean boolean cuts ---
eps     = 0.5;      // overcut past faces
outer_r = outer_d / 2;
inner_r = inner_d / 2;

difference() {
    // Annulus
    difference() {
        cylinder(h = thickness, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = thickness + 2 * eps, r = inner_r);
    }

    // Radial tick grooves in the top face
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, start_angle + i * 360 / tick_count])
            translate([outer_r - tick_length,
                       -tick_width / 2,
                       thickness - tick_depth])
                cube([tick_length + eps, tick_width, tick_depth + eps]);
    }
}
```

```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Units: mm. Prints flat on the bed, centred on the origin.

// ---- Ring dimensions ----
outer_d     = 60;    // outer diameter of the ring
inner_d     = 36;    // inner (bore) diameter of the ring
ring_t      = 5;     // ring thickness (Z)

// ---- Tick mark dimensions ----
tick_count  = 12;    // number of evenly spaced ticks
tick_w      = 1.5;   // groove width (tangential)
tick_depth  = 1;     // groove depth into top face
tick_len    = 3;     // radial length, measured inward from outer edge
tick_start_angle = 0; // first tick on +X axis (degrees)

// ---- Modelling helpers ----
eps         = 0.5;   // overshoot for clean boolean cuts
$fn         = 128;   // circle resolution

outer_r = outer_d / 2;
inner_r = inner_d / 2;

difference() {
    // Annulus body
    difference() {
        cylinder(h = ring_t, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = ring_t + 2 * eps, r = inner_r);
    }

    // Radial tick grooves in the top face
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, tick_start_angle + i * 360 / tick_count])
            translate([outer_r - tick_len,
                       -tick_w / 2,
                       ring_t - tick_depth])
                // extend past the outer edge and above the top face
                cube([tick_len + eps, tick_w, tick_depth + eps]);
    }
}
```

