// Anti-vibration foot for benchtop instrument
// Print orientation: wide base on bed (z = 0), narrow top at z = 15

$fn = 128;

// --- Dimensions (mm) ---
base_d      = 50;    // frustum diameter at bottom (z = 0)
top_d       = 36;    // frustum diameter at flat top
foot_h      = 15;    // total height of foot
recess_d    = 44;    // rubber pad recess diameter (bottom face)
recess_depth = 3;    // rubber pad recess depth
screw_d     = 4.5;   // through-hole diameter for screw

eps = 0.5;           // overcut for clean boolean differences

difference() {
    // Main frustum body
    cylinder(h = foot_h, d1 = base_d, d2 = top_d);

    // Rubber pad recess in bottom face
    translate([0, 0, -eps])
        cylinder(h = recess_depth + eps, d = recess_d);

    // Central screw through-hole along Z axis
    translate([0, 0, -eps])
        cylinder(h = foot_h + 2 * eps, d = screw_d);
}
