// Stiffened cover panel
plate_len   = 80;   // plate length (X)
plate_wid   = 80;   // plate width (Y)
plate_t     = 2;    // plate thickness (Z)
rib_t       = 2;    // rib thickness (X)
rib_h       = 6;    // rib height above plate
rib_count   = 3;    // number of ribs
rib_pitch   = 20;   // centre-to-centre spacing of ribs
overlap     = 0.01; // small overlap so ribs fuse with plate

union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_t]);

    // Ribs running full width along Y
    for (i = [0 : rib_count - 1]) {
        x_c = (i - (rib_count - 1)/2) * rib_pitch;
        translate([x_c - rib_t/2, -plate_wid/2, plate_t - overlap])
            cube([rib_t, plate_wid, rib_h + overlap]);
    }
}
