// Stiffened cover panel
// Print orientation: plate flat on the bed, ribs pointing up (+Z)

// ---- Plate ----
plate_len   = 120;   // plate length along X (mm)
plate_wid   = 60;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness, z = 0..3 (mm)

// ---- Ribs ----
rib_count   = 4;     // number of ribs
rib_thk     = 2;     // rib thickness along X (mm)
rib_h       = 4;     // rib height above plate, z = 3..7 (mm)
rib_pitch   = plate_len / (rib_count + 1);  // 24 mm centre-to-centre spacing
rib_overlap = 0.01;  // small overlap into plate for a clean union (mm)

$fn = 64;

// X position of rib i (centres at -36, -12, 12, 36)
function rib_x(i) = -plate_len/2 + (i + 1) * rib_pitch;

union() {
    // Base plate, centred in X and Y, sitting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running the full width along Y
    for (i = [0 : rib_count - 1])
        translate([rib_x(i) - rib_thk/2, -plate_wid/2, plate_thk - rib_overlap])
            cube([rib_thk, plate_wid, rib_h + rib_overlap]);
}
