        // Lower half of outer sphere (rim at z = 15)
        intersection() {
            translate([0, 0, bowl_cz]) sphere(r = bowl_r_outer);
            translate([-bowl_r_outer - 1, -bowl_r_outer - 1, -1])
                cube([2 * bowl_r_outer + 2, 2 * bowl_r_outer + 2, bowl_cz + 1]);
        }

        // Flat handle along +X, z = 11..15
        translate([handle_x0, -handle_w / 2, handle_top - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }

