// Pin hinge leaf, one half
// Plate lies on the bed, centred on the origin. Knuckles sit on segments 1 and 3 along the +Y edge.

$fn = 96;

// ---------- Dimensions ----------
plate_len   = 45;    // plate length along X
plate_wid   = 20;    // plate width along Y
plate_th    = 3;     // plate thickness along Z

n_seg       = 3;                    // number of knuckle segments along the length
seg_len     = plate_len / n_seg;    // 15 mm per segment
knuckle_d   = 7;     // knuckle outer diameter
axis_y      = 10;    // hinge axis Y position (the +Y edge)
axis_z      = 3.5;   // hinge axis Z position, equal to the knuckle radius so it sits on the bed
pin_d       = 3;     // pin hole diameter
eps         = 0.01;  // overlap for clean boolean cuts

// Segment indices that carry knuckles (0-based): 1st and 3rd segments
knuckle_segs = [0, 2];

// X start of a given segment
function seg_x0(i) = -plate_len/2 + i*seg_len;

// ---------- Model ----------
difference() {
    union() {
        // Flat plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_th]);

        // Knuckles
        for (i = knuckle_segs)
            translate([seg_x0(i), axis_y, axis_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole through each knuckle along the hinge axis
    for (i = knuckle_segs)
        translate([seg_x0(i) - eps, axis_y, axis_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = seg_len + 2*eps);
}
