// Pin hinge leaf, 3 knuckle segments, knuckles on segments 1 and 3
// Print orientation: plate flat on bed, knuckles up

$fn = 64;

// ---- Plate ----
plate_len   = 45;    // X length
plate_wid   = 25;    // Y width
plate_thk   = 3;     // Z thickness

// ---- Knuckles ----
