pin_d       = 2;                   // pin hole diameter
cut_ext     = 0.5;                 // cutter overrun past knuckle ends

// Knuckle segment indices (0-based): 1st and 3rd segments
knuckle_segs = [0, 2];

// X start of a given segment
function seg_x0(i) = -plate_len/2 + i*seg_len;

// cylinder along +X, starting at x0, length L
module x_cyl(x0, L, d, rot = 0) {
    translate([x0, axis_y, axis_z])
        rotate([0, 90, 0])
            rotate([0, 0, rot])
                cylinder(d = d, h = L);
}

difference() {
    union() {
        // Plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles
        for (i = knuckle_segs)
            x_cyl(seg_x0(i), seg_len, knuckle_d);
    }

    // Pin hole through each knuckle (rotated half a facet so a flat
    // faces down and the cutter never touches the plate top at z = 3)
    for (i = knuckle_segs)
        x_cyl(seg_x0(i) - cut_ext, seg_len + 2*cut_ext, pin_d, 180/$fn);
}
