// ---- Plate ----
plate_len   = 60;    // X length of plate (mm)
plate_wid   = 25;    // Y width of plate (mm)
plate_thk   = 2.5;   // Z thickness of plate (mm)

// ---- Knuckles ----
n_segments  = 5;                       // number of equal segments along X
seg_len     = plate_len / n_segments;  // 12 mm per segment
knuckle_d   = 6;     // knuckle outer diameter (mm)
axis_y      = 12.5;  // knuckle axis Y position (mm)
axis_z      = 3;     // knuckle axis Z position (mm)
knuckle_idx = [0, 2, 4]; // 1st, 3rd and 5th segments carry knuckles

// ---- Pin hole ----
pin_d       = 2;     // pin hole diameter (mm)
eps         = 0.5;   // overshoot for clean boolean cuts (mm)

module plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module knuckles() {
    for (i = knuckle_idx)
        translate([-plate_len/2 + i*seg_len, axis_y, axis_z])
            rotate([0, 90, 0])
                cylinder(d = knuckle_d, h = seg_len);
}

module pin_hole() {
    translate([-plate_len/2 - eps, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}

difference() {
    union() {
        plate();
        knuckles();
    }
    pin_hole();
}
