// Star-shaped indexing wheel
// Units: mm

// ---- Parameters ----
num_points     = 6;     // number of star points
outer_r        = 35;    // radius of outer (tip) points from centre
inner_r        = 21;    // radius of inner (valley) points from centre
plate_thick    = 4;     // plate thickness (Z)
hole_d         = 8;     // centre through-hole diameter
cut_extra      = 0.5;   // extension of cutting shapes past faces
$fn            = 96;    // resolution for curved shapes

// ---- Star outline points ----
// Alternates outer/inner, first outer point on +X axis
function star_pts() = [
    for (i = [0 : 2 * num_points - 1])
        let (
            a = i * 180 / num_points,
            r = (i % 2 == 0) ? outer_r : inner_r
        )
        [r * cos(a), r * sin(a)]
];

// ---- Part ----
difference() {
    // Star plate resting on the bed
    linear_extrude(height = plate_thick)
        polygon(points = star_pts());

    // Centre through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_thick + 2 * cut_extra, $fn = 96);
}
