module frustum() {
    b = base_size / 2;
    t = top_size / 2;
    polyhedron(
        points = [
            [-b, -b, 0], [ b, -b, 0], [ b,  b, 0], [-b,  b, 0],              // bottom
            [-t, -t, block_height], [ t, -t, block_height],
            [ t,  t, block_height], [-t,  t, block_height]                   // top
        ],
        faces = [
            [0, 1, 2, 3],   // bottom
            [4, 5, 1, 0],   // front (-Y)
            [5, 6, 2, 1],   // right (+X)
            [6, 7, 3, 2],   // back (+Y)
            [7, 4, 0, 3],   // left (-X)
            [7, 6, 5, 4]    // top
        ]
    );
}

difference() {
    frustum();
    // square pocket in top face
    translate([-pocket_size / 2, -pocket_size / 2, block_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
