// Flat part, printed lying on the bed, centred on the origin

// ---------- Parameters ----------
thickness      = 6;    // overall wheel thickness (Z)
rim_od         = 60;   // rim outer diameter
rim_width      = 5;    // radial width of rim ring
hub_d          = 14;   // hub outer diameter
axle_d         = 5;    // axle hole diameter
spoke_count    = 4;    // number of spokes
spoke_width    = 5;    // spoke width
spoke_start_angle = 0; // first spoke along +X axis
eps            = 0.5;  // overlap / cut extension

$fn = 128;

// ---------- Derived ----------
rim_r       = rim_od / 2;
rim_inner_r = rim_r - rim_width;
hub_r       = hub_d / 2;

// ---------- Model ----------
difference() {
    union() {
        // Outer rim ring
        difference() {
            cylinder(h = thickness, r = rim_r);
            translate([0, 0, -eps])
                cylinder(h = thickness + 2 * eps, r = rim_inner_r);
        }

        // Hub
        cylinder(h = thickness, r = hub_r);

        // Spokes (overlap slightly into hub and rim)
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start_angle + i * 360 / spoke_count])
                translate([hub_r - eps, -spoke_width / 2, 0])
                    cube([(rim_inner_r - hub_r) + 2 * eps, spoke_width, thickness]);
    }

    // Axle hole through hub
    translate([0, 0, -eps])
        cylinder(h = thickness + 2 * eps, d = axle_d);
}
