```openscad
// Spoked wheel for a small sample cart
// Print orientation: flat on bed, centred on origin

$fn = 128;

// --- Dimensions (mm) ---
thickness     = 5;    // overall part thickness (Z)
rim_od        = 100;  // rim outer diameter
rim_width     = 6;    // rim radial width
hub_d         = 14;   // hub outer diameter
axle_d        = 8;    // axle hole diameter
spoke_count   = 8;    // number of spokes
spoke_width   = 5;    // spoke width
eps           = 0.5;  // cutter overshoot

// --- Derived ---
rim_or = rim_od / 2;
rim_ir = rim_or - rim_width;
hub_r  = hub_d / 2;
// spokes overlap into hub and rim for a solid union
spoke_start = hub_r - 1;
spoke_len   = (rim_ir + 1) - spoke_start;

difference() {
    union() {
        // Rim
        difference() {
            cylinder(r = rim_or, h = thickness);
            translate([0, 0, -eps])
                cylinder(r = rim_ir, h = thickness + 2 * eps);
        }
        // Hub
        cylinder(r = hub_r, h = thickness);
        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([spoke_start, -spoke_width / 2, 0])
                    cube([spoke_len, spoke_width, thickness]);
    }
    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
